        if n == 1:
            return ['0'], []
        else:
            inputs = [f'x{i}' for i in range(n)]
            gates = []
            for _ in range(n - 1):
                gate_type = random.choice(['AND', 'OR'])
                gate_inputs = random.sample(inputs, 2)
                output = f'y{len(gates)}'
                gates.append((gate_type, gate_inputs, output))
                inputs.append(output)
            return inputs, gates

